let current = 0;

async function loadSlides() {
  const res = await fetch("slides.json");
  slides = await res.json();
  render();
}

function render() {
  renderSidebar();
  renderSlide();
}

function goTo(index) {
  if (!slides.length) return;
  if (index < 0 || index > slides.length - 1) return;
  current = index;
  render();
}

function renderSidebar() {
  const list = document.getElementById("slideList");
  list.innerHTML = "";

  slides.forEach((slide, i) => {
    const item = document.createElement("div");
    item.className = "slide-item";
    if (i === current) {
      item.classList.add("active");
    }
    item.textContent = \`\${i + 1}. \${slide.title}\`;

    item.onclick = () => {
      goTo(i);
    };

    list.appendChild(item);
  });
}

function renderSlide() {
  const slide = slides[current];
  if (!slide) return;

  const container = document.getElementById("slide");

  // Restart the fade/slide-in transition so changes feel smooth, not abrupt.
  container.classList.remove("active");
  void container.offsetWidth;

  document.getElementById("title").textContent = slide.title;
  document.getElementById("subtitle").textContent = slide.subtitle;
  document.getElementById("figure").src = slide.image;
  document.getElementById("caption").textContent = slide.caption;

  const bulletList = document.getElementById("bulletList");
  bulletList.innerHTML = "";
  slide.bullets.forEach((b) => {
    const li = document.createElement("li");
    li.textContent = b;
    bulletList.appendChild(li);
  });

  container.classList.add("active");
}

document.getElementById("nextBtn").onclick = () => {
  goTo(current + 1);
};

document.getElementById("prevBtn").onclick = () => {
  goTo(current - 1);
};

document.addEventListener("keydown", (e) => {
  if (e.key === "ArrowRight") {
    e.preventDefault();
    goTo(current + 1);
  } else if (e.key === "ArrowLeft") {
    e.preventDefault();
    goTo(current - 1);
  }
});

loadSlides();
`;

